{
  "name": "Tecan自动液体处理工作站",
  "name_en": "Tecan automated liquid handling workstation",
  "manufacturer": "Tecan",
  "description": "这是一类用于实验室自动移液和样品处理的液体处理工作站。设备在工作台甲板上放置载架、孔板、试剂槽、比色皿、磁力模块和一次性吸头架，并通过自动吸液、分液、换头和废弃处理完成样品制备、试剂分装、PCR体系构建等流程。",
  "description_en": "This is an automated liquid handling workstation used for laboratory pipetting and sample processing. The instrument arranges carriers, microplates, reagent troughs, cuvettes, magnetic modules, and disposable tip racks on a deck, and performs aspiration, dispensing, tip changes, and waste handling for tasks such as sample preparation, reagent distribution, and PCR setup.",
  "tag_hints": [
    "automated liquid handling",
    "Tecan Freedom EVO",
    "deck layout and labware carriers",
    "disposable tip racks",
    "microplate well selection",
    "reagent dispensing",
    "sample preparation"
  ],
  "actions": [
    {
      "action_name": "auto-parse_worktable_file",
      "description": "解析工作台布局文件",
      "description_en": "parse the worktable layout file"
    },
    {
      "action_name": "auto-add_new_labware",
      "description": "添加新的实验室器皿",
      "description_en": "add a new labware item"
    },
    {
      "action_name": "auto-add_labware",
      "description": "添加实验室器皿",
      "description_en": "add labware"
    },
    {
      "action_name": "auto-get_current_labware",
      "description": "获取当前实验室器皿",
      "description_en": "get the current labware"
    },
    {
      "action_name": "auto-set_current",
      "description": "设置当前实验室器皿",
      "description_en": "set the current labware"
    },
    {
      "action_name": "auto-get_labware",
      "description": "获取实验室器皿",
      "description_en": "get labware"
    },
    {
      "action_name": "auto-set_first_pos",
      "description": "设置首个位置",
      "description_en": "set the first position"
    },
    {
      "action_name": "auto-retire_labware",
      "description": "停用实验室器皿",
      "description_en": "retire labware"
    },
    {
      "action_name": "auto-replace_with_new",
      "description": "用新的实验室器皿替换",
      "description_en": "replace with new labware"
    },
    {
      "action_name": "auto-set_def_DiTi",
      "description": "设置默认一次性吸头类型",
      "description_en": "set the default disposable tip type"
    },
    {
      "action_name": "auto-get_DITI_series",
      "description": "获取一次性吸头架系列",
      "description_en": "get the disposable tip rack series"
    },
    {
      "action_name": "auto-log",
      "description": "记录工作台或器皿状态",
      "description_en": "log the worktable or labware state"
    },
    {
      "action_name": "auto-select",
      "description": "选择孔位、位置或器皿",
      "description_en": "select wells, positions, or labware"
    },
    {
      "action_name": "auto-vol",
      "description": "获取或定义体积",
      "description_en": "get or define the volume"
