      "description_en": "create a labware or configuration object"
    },
    {
      "action_name": "auto-init_wells",
      "description": "初始化孔位",
      "description_en": "initialize wells"
    },
    {
      "action_name": "auto-autoselect",
      "description": "自动选择孔位或位置",
      "description_en": "automatically select wells or positions"
    },
    {
      "action_name": "auto-offset",
      "description": "获取或定义偏移量",
      "description_en": "get or define the offset"
    },
    {
      "action_name": "auto-offsetFromName",
      "description": "按名称获取偏移量",
      "description_en": "get the offset from a name"
