      "description_en": "define a new position"
    },
    {
      "action_name": "auto-posAtParallelMove",
      "description": "获取并行移动时的位置",
      "description_en": "get the position for a parallel move"
    },
    {
      "action_name": "auto-parallelOrder",
      "description": "获取或定义并行移动顺序",
      "description_en": "get or define the parallel movement order"
    },
    {
      "action_name": "auto-offsetAtParallelMove",
      "description": "获取并行移动时的偏移量",
      "description_en": "get the offset for a parallel move"
    },
    {
      "action_name": "auto-moveParallel",
